// TestPDFOpenAIFixture is the PDF container on a real producer's file rather
// than a synthesised one. The document was generated by ChatGPT, so its carrier
// is what that pipeline writes: a catalog at generation 1, /Type /FileSpec, a
// literal-string /Subtype, and the manifest added by an incremental update. It
// is also the only fixture here whose manifest carries no timestamp at all.
func TestPDFOpenAIFixture(t *testing.T) {
	data, err := os.ReadFile("testdata/c2pa_chatgpt.pdf")
	if err != nil {
		t.Fatal(err)
	}

	info := Read(context.Background(), PDF, bytes.NewReader(data))
	for _, tc := range []struct{ name, got, want string }{
		{"ClaimGenerator", info.ClaimGenerator, "ChatGPT"},
		{"SoftwareAgent", info.SoftwareAgent, "gpt-5.6-sol/gpt-5.6-sol"},
		{"Title", info.Title, "image.pdf"},
		{"SignedBy", info.SignedBy, "OpenAI Media Service"},
	} {
		if tc.got != tc.want {
			t.Errorf("Read %s=%q want %q", tc.name, tc.got, tc.want)
		}
	}
	if !info.AIGenerated {
		t.Error("Read AIGenerated=false, want true")
	}
	if !info.SignedAt.IsZero() {
		t.Errorf("Read SignedAt=%s, want zero: the manifest carries no timestamp", info.SignedAt)
	}

	// Pinned inside the leaf's validity window (2026-04-22 to 2027-04-23). There
	// is no timestamp to pin to, so an unpinned test would start failing the day
	// the leaf expires.
	inWindow := time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
	r := Validate(context.Background(), PDF, bytes.NewReader(data),
		WithClock(func() time.Time { return inWindow }))

	if !r.Valid {
		t.Fatalf("expected valid, got %v", codes(r))
	}
	for _, code := range []StatusCode{
		StatusClaimSignatureValidated,
		StatusSigningCredentialTrusted,
		StatusAssertionDataHashMatch,
	} {
		if !r.Has(code) {
			t.Errorf("expected %s; statuses=%v", code, codes(r))
		}
	}
	// No timestamp at all, where the PNG fixture has an untrusted one.
	if !r.Has(StatusTimeStampMissing) {
		t.Errorf("expected %s; statuses=%v", StatusTimeStampMissing, codes(r))
	}
	if len(r.SignerChain) != 2 {
		t.Errorf("SignerChain has %d certs, want 2", len(r.SignerChain))
	}
}

// --- synthetic PDF builders --------------------------------------------------

// pdfDoc assembles a PDF in memory: a header, indirect objects in the order
// they are appended, and a trailer naming the catalog. It writes no xref table
// — the extractor is a lexical scanner, and what these tests exercise is the
// object bytes. Appending more objects and a second trailer after a first one
// is exactly the shape of a PDF incremental update.
type pdfDoc struct {
	b []byte
	// offs records where each object number's definition starts, which is what
	// a cross-reference table holds; xrefTrailer needs it.
	offs map[int]int
}

func newPDFDoc() *pdfDoc { return &pdfDoc{b: []byte("%PDF-1.7\n"), offs: map[int]int{}} }

func (d *pdfDoc) obj(num int, body string) *pdfDoc {
	d.offs[num] = len(d.b)
	d.b = append(d.b, fmt.Sprintf("%d 0 obj\n%s\nendobj\n", num, body)...)
	return d
}

// stream appends a stream object. length is the literal text of the /Length
// entry, so a test can make it lie or make it indirect; "" writes the truth.
func (d *pdfDoc) stream(num int, dict string, payload []byte, length string) *pdfDoc {
	if length == "" {
		length = fmt.Sprint(len(payload))
	}
	d.offs[num] = len(d.b)
	d.b = append(d.b, fmt.Sprintf("%d 0 obj\n<< %s /Length %s >>\nstream\n", num, dict, length)...)
	d.b = append(d.b, payload...)
	d.b = append(d.b, "\nendstream\nendobj\n"...)
	return d
}

func (d *pdfDoc) trailer(root int) *pdfDoc {
	d.b = append(d.b, fmt.Sprintf("trailer\n<< /Root %d 0 R >>\nstartxref\n0\n%%%%EOF\n", root)...)
	return d
}

// xrefTrailer writes a real cross-reference table over every object appended so
// far and a startxref holding that table's own offset — the route a conforming
// reader takes to the catalog. trailer() writes a startxref of 0, which no
// reader can follow, so only a document ending here exercises the xref path.
func (d *pdfDoc) xrefTrailer(root int) *pdfDoc {
	high := 0
	for num := range d.offs {
		high = max(high, num)
	}
	start := len(d.b)
	d.b = append(d.b, fmt.Sprintf("xref\n0 %d\n0000000000 65535 f \n", high+1)...)
	for num := 1; num <= high; num++ {
		if off, ok := d.offs[num]; ok {
			d.b = append(d.b, fmt.Sprintf("%010d 00000 n \n", off)...)
		} else {
			d.b = append(d.b, "0000000000 65535 f \n"...)
		}
	}
	d.b = append(d.b, fmt.Sprintf("trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%%%EOF\n",
		high+1, root, start)...)
	return d
}

func (d *pdfDoc) bytes() []byte { return d.b }

// append adds raw bytes with no cross-reference entry of their own, which is
// what tampering after %%EOF looks like.
func (d *pdfDoc) append(s string) *pdfDoc {
	d.b = append(d.b, s...)
	return d
}

// clone copies the document, so an update section can be appended to a fresh
// copy without disturbing the bytes of the original.
func (d *pdfDoc) clone() *pdfDoc {
	c := &pdfDoc{b: append([]byte{}, d.b...), offs: map[int]int{}}
	for num, off := range d.offs {
		c.offs[num] = off
	}
	return c
}

const (
	pdfEmbeddedFileDict = "/Type /EmbeddedFile /Subtype /application#2Fc2pa"
	pdfC2PAFilespec     = "<< /Type /Filespec /F (c2pa.c2pa) /UF (c2pa.c2pa) " +
		"/AFRelationship /C2PA_Manifest /EF << /F 4 0 R >> >>"
)

// synthPDF builds a document whose catalog associates one C2PA manifest, the
// layout spec §A.4 describes: catalog /AF → file specification → /EF stream.
func synthPDF(t *testing.T, store []byte, compress bool) []byte {
	t.Helper()
	dict, payload := pdfEmbeddedFileDict, store
	if compress {
		dict, payload = dict+" /Filter /FlateDecode", zlibBytes(t, store)
	}
	return newPDFDoc().
		obj(1, "<< /Type /Catalog /Pages 2 0 R /AF [3 0 R] >>").
		obj(2, "<< /Type /Pages /Kids [] /Count 0 >>").
		obj(3, pdfC2PAFilespec).
		stream(4, dict, payload, "").
		trailer(1).
		bytes()
}

// zlibBytes compresses b the way a producer writes a /FlateDecode stream.
func zlibBytes(t *testing.T, b []byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := zlib.NewWriter(&buf)
	if _, err := zw.Write(b); err != nil {
		t.Fatal(err)
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

// --- manifest extraction -----------------------------------------------------

func TestPDFJUMBF(t *testing.T) {
	store := synthJUMB([]byte("manifest store"))
	ctx := context.Background()

	t.Run("uncompressed embedded file", func(t *testing.T) {
		if got := pdfJUMBF(ctx, synthPDF(t, store, false)); !bytes.Equal(got, store) {
			t.Fatalf("store not extracted: got %q", got)
		}
	})
	t.Run("flate-compressed embedded file", func(t *testing.T) {
		if got := pdfJUMBF(ctx, synthPDF(t, store, true)); !bytes.Equal(got, store) {
			t.Fatalf("compressed store not inflated: got %q", got)
		}
	})
	t.Run("padded stream trimmed to the superbox", func(t *testing.T) {
		padded := append(append([]byte{}, store...), make([]byte, 64)...)
		if got := pdfJUMBF(ctx, synthPDF(t, padded, false)); !bytes.Equal(got, store) {
			t.Fatalf("padding not trimmed: got %d bytes, want %d", len(got), len(store))
		}
	})
	t.Run("no associated files", func(t *testing.T) {
		doc := newPDFDoc().obj(1, "<< /Type /Catalog /Pages 2 0 R >>").trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); got != nil {
			t.Fatalf("document with no manifest yielded %q", got)
		}
	})
	t.Run("foreign relationship ignored", func(t *testing.T) {
		doc := newPDFDoc().
			obj(1, "<< /Type /Catalog /AF [3 0 R] >>").
			obj(3, "<< /Type /Filespec /F (notes.txt) /AFRelationship /Supplement /EF << /F 4 0 R >> >>").
			stream(4, "/Type /EmbeddedFile", store, "").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); got != nil {
			t.Fatalf("non-C2PA associated file yielded %q", got)
		}
	})
	t.Run("payload that is not JUMBF", func(t *testing.T) {
		if got := pdfJUMBF(ctx, synthPDF(t, []byte("not a manifest at all"), false)); got != nil {
			t.Fatalf("non-JUMBF payload yielded %q", got)
		}
	})
	t.Run("not a PDF", func(t *testing.T) {
		if got := pdfJUMBF(ctx, []byte("\x89PNG\r\n\x1a\n1 0 obj stream")); got != nil {
			t.Fatalf("non-PDF input yielded %q", got)
		}
	})
	t.Run("cancelled context", func(t *testing.T) {
		cancelled, cancel := context.WithCancel(ctx)
		cancel()
		if got := pdfJUMBF(cancelled, synthPDF(t, store, false)); got != nil {
			t.Fatalf("cancelled ctx yielded %q", got)
		}
	})
}

// TestPDFJUMBF_DeclaredLengthLies pins that /Length is a hint: too large, too
// small, or an indirect reference the scanner does not resolve, the payload is
// still bounded by the `endstream` keyword.
func TestPDFJUMBF_DeclaredLengthLies(t *testing.T) {
	store := synthJUMB([]byte("manifest store"))
	for name, length := range map[string]string{
		"far too large": "999999999",
		"too small":     "3",
		"negative":      "-40",
		"indirect ref":  "9 0 R",
	} {
		t.Run(name, func(t *testing.T) {
			doc := newPDFDoc().
				obj(1, "<< /Type /Catalog /AF [3 0 R] >>").
				obj(3, pdfC2PAFilespec).
				stream(4, pdfEmbeddedFileDict, store, length).
				trailer(1).bytes()
			if got := pdfJUMBF(context.Background(), doc); !bytes.Equal(got, store) {
				t.Fatalf("/Length %s: got %q want the store", length, got)
			}
		})
	}
}

// TestPDFInt pins that an indirect reference reports absent rather than its
// object number. The stream reader survives either way, because it verifies a
// declared length against `endstream`, but a future caller without that fallback
// would otherwise read 9 as a byte count.
func TestPDFInt(t *testing.T) {
	for name, tc := range map[string]struct {
		dict string
		want int
		ok   bool
	}{
		"direct":                  {"<< /Length 40 >>", 40, true},
		"indirect ref":            {"<< /Length 9 0 R >>", 0, false},
		"indirect ref, no spaces": {"<< /Length 9 0 R/Type /X >>", 0, false},
		"absent":                  {"<< /Type /X >>", 0, false},
		"not a number":            {"<< /Length /X >>", 0, false},
	} {
		t.Run(name, func(t *testing.T) {
			got, ok := pdfInt([]byte(tc.dict), "Length")
			if got != tc.want || ok != tc.ok {
				t.Fatalf("pdfInt(%q) = (%d, %v), want (%d, %v)", tc.dict, got, ok, tc.want, tc.ok)
			}
		})
	}
}

// TestPDFJUMBF_IncrementalUpdate pins the "last definition wins" rule: an
// update appends a new catalog and a new manifest without touching the original
// bytes, and the newest association is the current one.
func TestPDFJUMBF_IncrementalUpdate(t *testing.T) {
	first := synthJUMB([]byte("first manifest"))
	second := synthJUMB([]byte("second manifest"))
	ctx := context.Background()

	base := newPDFDoc().
		obj(1, "<< /Type /Catalog /Pages 2 0 R /AF [3 0 R] >>").
		obj(2, "<< /Type /Pages /Kids [] /Count 0 >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict, first, "").
		trailer(1)
	if got := pdfJUMBF(ctx, base.bytes()); !bytes.Equal(got, first) {
		t.Fatalf("base document: got %q want the first manifest", got)
	}

	t.Run("re-signed", func(t *testing.T) {
		doc := base.clone().
			obj(1, "<< /Type /Catalog /Pages 2 0 R /AF [5 0 R] >>").
			obj(5, "<< /Type /Filespec /F (c2pa.c2pa) /AFRelationship /C2PA_Manifest /EF << /F 6 0 R >> >>").
			stream(6, pdfEmbeddedFileDict, second, "").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); !bytes.Equal(got, second) {
			t.Fatalf("got %q want the manifest the update associated", got)
		}
	})
	t.Run("association dropped by the update", func(t *testing.T) {
		// The newest catalog associates no C2PA manifest, but §15.5.2.2 keeps a
		// store from an earlier update section valid, so the first one stands.
		doc := base.clone().
			obj(1, "<< /Type /Catalog /Pages 2 0 R /AF [5 0 R] >>").
			obj(5, "<< /Type /Filespec /F (notes.txt) /AFRelationship /Supplement >>").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); !bytes.Equal(got, first) {
			t.Fatalf("got %q want the earlier update's manifest", got)
		}
	})
}

// pdfEmptyJUMB is a well-formed superbox carrying no manifest: the payload a
// decoy catalog points at to make a signed document read as unsigned.
var pdfEmptyJUMB = []byte{0, 0, 0, 8, 'j', 'u', 'm', 'b'}

// TestPDFJUMBF_AuthoritativeCatalog pins that only the cross-reference section
// the last startxref names can say which object is the catalog. Taking the last
// /Root, or the last lexical definition of an object number, lets bytes no
// reader treats as part of the document redirect it — and a decoy pointing at an
// empty superbox turns a signed manifest into an absent one, which costs no
// cryptography and reads as "no provenance" rather than as tampering.
func TestPDFJUMBF_AuthoritativeCatalog(t *testing.T) {
	store := synthJUMB([]byte("manifest store"))
	ctx := context.Background()

	genuine := newPDFDoc().
		obj(1, "<< /Type /Catalog /Pages 2 0 R /AF [3 0 R] >>").
		obj(2, "<< /Type /Pages /Kids [] /Count 0 >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict, store, "").
		xrefTrailer(1)
	if got := pdfJUMBF(ctx, genuine.bytes()); !bytes.Equal(got, store) {
		t.Fatalf("genuine document: got %q want the store", got)
	}

	decoy := fmt.Sprintf("900 0 obj\n<< /Type /Catalog /AF [901 0 R] >>\nendobj\n"+
		"901 0 obj\n<< /Type /Filespec /AFRelationship /C2PA_Manifest"+
		" /EF << /F 902 0 R >> >>\nendobj\n"+
		"902 0 obj\n<< /Type /EmbeddedFile /Length %d >>\nstream\n%s\nendstream\nendobj\n",
		len(pdfEmptyJUMB), pdfEmptyJUMB)

	t.Run("trailer appended after EOF", func(t *testing.T) {
		// No cross-reference section of its own, so startxref still names the
		// genuine table and these bytes are not part of the document.
		tampered := genuine.clone().
			append(decoy + "trailer\n<< /Size 903 /Root 900 0 R >>\n").bytes()
		t.Logf("%d bytes appended", len(tampered)-len(genuine.bytes()))
		if got := pdfJUMBF(ctx, tampered); !bytes.Equal(got, store) {
			t.Fatalf("appended decoy catalog won: got %q want the genuine store", got)
		}
	})

	t.Run("phantom catalog redefining the object", func(t *testing.T) {
		// The decoy redefines object 1 rather than naming a new one, so it needs
		// no /Root of its own: the lexical "last definition wins" rule hands it
		// the document.
		tampered := genuine.clone().
			append("1 0 obj\n<< /Type /Catalog /AF [901 0 R] >>\nendobj\n" +
				decoy).bytes()
		if got := pdfJUMBF(ctx, tampered); !bytes.Equal(got, store) {
			t.Fatalf("phantom catalog won: got %q want the genuine store", got)
		}
	})
}

// TestPDFJUMBF_MarkerFallback covers the documents whose pointer chain is not
// visible to a lexical scan — a catalog or file specification compressed into an
// object stream. The embedded file stream itself always is, so the extractor
// falls back to the spec's own markers on it.
func TestPDFJUMBF_MarkerFallback(t *testing.T) {
	store := synthJUMB([]byte("manifest store"))
	ctx := context.Background()

	t.Run("catalog not visible", func(t *testing.T) {
		// /Root names an object that is not in the plain object bytes.
		doc := newPDFDoc().
			obj(3, pdfC2PAFilespec).
			stream(4, pdfEmbeddedFileDict, store, "").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); !bytes.Equal(got, store) {
			t.Fatalf("relationship fallback failed: got %q", got)
		}
	})
	t.Run("only the embedded file visible", func(t *testing.T) {
		doc := newPDFDoc().
			stream(4, pdfEmbeddedFileDict, store, "").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); !bytes.Equal(got, store) {
			t.Fatalf("/Subtype fallback failed: got %q", got)
		}
	})
	t.Run("unmarked embedded file is not assumed", func(t *testing.T) {
		doc := newPDFDoc().
			stream(4, "/Type /EmbeddedFile /Subtype /text#2Fplain", store, "").
			trailer(1).bytes()
		if got := pdfJUMBF(ctx, doc); got != nil {
			t.Fatalf("unmarked embedded file yielded %q", got)
		}
	})
}

// pdfObjStmDoc hides the pointer chain in an object stream: the catalog and the
// file specification live inside a /Type /ObjStm, the xref stream's dictionary
// names /Root, and only the manifest stream is plainly visible. It carries no
// /Subtype, as the one real producer file available does not.
func pdfObjStmDoc(t *testing.T, store []byte) []byte {
	t.Helper()
	inner := map[int]string{
		1: "<< /Type /Catalog /Pages 2 0 R /AF [3 0 R] >>",
		3: "<< /Type /Filespec /F (c2pa.c2pa) /AFRelationship /C2PA_Manifest" +
			" /EF << /F 4 0 R >> >>",
	}
	var hdr, bodies string
	for _, num := range []int{1, 3} {
		hdr += fmt.Sprintf("%d %d ", num, len(bodies))
		bodies += inner[num] + " "
	}

	d := newPDFDoc()
	d.stream(5, fmt.Sprintf("/Type /ObjStm /N 2 /First %d /Filter /FlateDecode", len(hdr)),
		zlibBytes(t, []byte(hdr+bodies)), "")
	d.stream(4, "/Type /EmbeddedFile", store, "")
	xref := len(d.bytes())
	d.stream(6, "/Type /XRef /Size 7 /Root 1 0 R /W [1 2 1]", []byte{0}, "")
	return d.append(fmt.Sprintf("startxref\n%d\n%%%%EOF\n", xref)).bytes()
}

// TestPDFJUMBF_ObjectStreamChain pins that a chain compressed into an object
// stream is still followed. §7.5.7 forbids a stream object inside an object
// stream, but the §A.4.1 markers live on the file specification dictionary,
// which it permits — so the manifest bytes being visible does not make the store
// identifiable, and a conforming document like this one yielded nothing.
func TestPDFJUMBF_ObjectStreamChain(t *testing.T) {
	store := synthJUMB([]byte("manifest store"))
	doc := pdfObjStmDoc(t, store)
	if bytes.Contains(doc, []byte(pdfC2PARelationship)) {
		t.Fatal("the relationship marker is still visible in the plain bytes")
	}
	if got := pdfJUMBF(context.Background(), doc); !bytes.Equal(got, store) {
		t.Fatalf("object-stream chain not recovered: got %d bytes, want %d", len(got), len(store))
	}
}

// TestPDFJUMBF_Malformed feeds every truncation of a good document plus a set
// of hand-broken ones. Nothing may panic, hang, or invent a manifest.
func TestPDFJUMBF_Malformed(t *testing.T) {
	ctx := context.Background()
	doc := synthPDF(t, synthJUMB([]byte("manifest store")), true)
	for n := 0; n < len(doc); n++ {
		if got := pdfJUMBF(ctx, doc[:n]); got != nil && !bytes.HasPrefix(got, []byte("\x00")) {
			t.Fatalf("truncated to %d bytes yielded %q", n, got)
		}
	}

	for name, broken := range map[string][]byte{
		"header only":          []byte("%PDF-1.7\n"),
		"unterminated object":  []byte("%PDF-1.7\n1 0 obj\n<< /Type /Catalog /AF [3 0 R] >>"),
		"stream never ends":    []byte("%PDF-1.7\n4 0 obj\n<< /Subtype /application#2Fc2pa /Length 8 >>\nstream\n"),
		"self-referential AF":  []byte("%PDF-1.7\n1 0 obj\n<< /Type /Catalog /AF [1 0 R] >>\nendobj\ntrailer\n<< /Root 1 0 R >>"),
		"absurd object number": []byte("%PDF-1.7\n99999999999999999999 0 obj\n<< /AFRelationship /C2PA_Manifest >>\nendobj\n"),
		"garbage flate":        []byte("%PDF-1.7\n4 0 obj\n<< /Subtype /application#2Fc2pa /Filter /FlateDecode /Length 4 >>\nstream\n\xff\xff\xff\xff\nendstream\nendobj\n"),
	} {
		if got := pdfJUMBF(ctx, broken); got != nil {
			t.Errorf("%s: yielded %q", name, got)
		}
	}
}

// TestPDFJUMBF_PathologicalCost pins the bounds that keep the scan linear. An
// object header with no `endobj` runs its body to the end of the file, and a
// repeated marker offers a fresh candidate stream per copy; unbounded, either
// would cost a full scan per object. The test only has to finish.
func TestPDFJUMBF_PathologicalCost(t *testing.T) {
	ctx := context.Background()

	t.Run("headers with no endobj", func(t *testing.T) {
		doc := append([]byte("%PDF-1.7\n"), bytes.Repeat([]byte("1 0 obj\n"), 100_000)...)
		doc = append(doc, bytes.Repeat([]byte{0xAB}, 1<<20)...)
		if got := pdfJUMBF(ctx, doc); got != nil {
			t.Fatalf("yielded %d bytes", len(got))
		}
	})
	t.Run("repeated marker, no endstream", func(t *testing.T) {
		doc := append([]byte("%PDF-1.7\n"),
			bytes.Repeat([]byte("1 0 obj\n<< /Subtype /application#2Fc2pa /Length 99999 >>\nstream\n"), 50_000)...)
		if got := pdfJUMBF(ctx, doc); got != nil {
			t.Fatalf("yielded %d bytes", len(got))
		}
	})
}

// pdfOpenArrayDoc builds kib kibibytes of a repeated token behind one real
// object, so the object index is non-empty and /Root resolution actually runs.
func pdfOpenArrayDoc(kib int, tok string) []byte {
	doc := append([]byte("%PDF-1.7\n"), "1 0 obj\n<< /Type /Catalog >>\nendobj\n"...)
	return append(doc, bytes.Repeat([]byte(tok), kib*1024/len(tok))...)
}

// TestPDFJUMBF_UnterminatedArrayCost pins a ceiling on the `/Root[` shape. `[`
// is a delimiter, so the name token matches and opens an array; searching for
// the `]` that never arrives costs the rest of the buffer, once per /Root, over
// every /Root. The ceilings are wall-clock because the growth rate is the
// defect: unbounded, 1 MiB cost ~1.5s and Read's cap is 16 MiB of it.
func TestPDFJUMBF_UnterminatedArrayCost(t *testing.T) {
	t.Run("bounded array window", func(t *testing.T) {
		doc := pdfOpenArrayDoc(1024, "/Root[")
		start := time.Now()
		if got := pdfJUMBF(context.Background(), doc); got != nil {
			t.Fatalf("yielded %d bytes", len(got))
		}
		if d := time.Since(start); d > 300*time.Millisecond {
			t.Fatalf("1 MiB of unterminated arrays took %v, want under 300ms", d)
		}
	})

	t.Run("deadline honoured", func(t *testing.T) {
		doc := pdfOpenArrayDoc(1024, "/Root[")
		ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
		defer cancel()
		start := time.Now()
		pdfJUMBF(ctx, doc)
		if d := time.Since(start); d > 400*time.Millisecond {
			t.Fatalf("a 50ms deadline did not stop the scan: took %v", d)
		}
	})
}

// TestPDFJUMBF_CompressionBomb pins that inflation is capped: a stream that
// expands far past maxPDFInflate returns rather than exhausting memory.
func TestPDFJUMBF_CompressionBomb(t *testing.T) {
	bomb := zlibBytes(t, make([]byte, maxPDFInflate+(64<<20)))
	doc := newPDFDoc().
		obj(1, "<< /Type /Catalog /AF [3 0 R] >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict+" /Filter /FlateDecode", bomb, "").
		trailer(1).bytes()
	if got := pdfJUMBF(context.Background(), doc); got != nil {
		t.Fatalf("compression bomb yielded %d bytes", len(got))
	}
}

